import 'package:flutter/material.dart';
import 'package:get_it/get_it.dart';
import 'hr_service.dart';
class HrScreen extends StatefulWidget{const HrScreen({super.key});@override State<HrScreen> createState()=>_HrScreenState();}
class _HrScreenState extends State<HrScreen>{final s=GetIt.I<HrService>();int tab=0;final no=TextEditingController(),first=TextEditingController(),last=TextEditingController(),email=TextEditingController(),join=TextEditingController();@override void initState(){super.initState();s.loadEmployees();}@override void dispose(){for(final c in[no,first,last,email,join])c.dispose();super.dispose();}Widget f(String l,TextEditingController c)=>Padding(padding:const EdgeInsets.only(bottom:10),child:TextField(controller:c,decoration:InputDecoration(labelText:l,border:const OutlineInputBorder())));@override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('Human Resources')),body:Column(children:[SingleChildScrollView(scrollDirection:Axis.horizontal,child:Row(children:['Employees','Attendance','Leave','Payroll','Recruitment','Performance','Training','Compliance'].asMap().entries.map((e)=>Padding(padding:const EdgeInsets.all(4),child:ChoiceChip(label:Text(e.value),selected:tab==e.key,onSelected:(_)=>setState(()=>tab=e.key)))).toList())),Expanded(child:Padding(padding:const EdgeInsets.all(16),child:_body()))]));Widget _body(){if(tab==0)return _employees();if(tab==1)return _attendance();return Center(child:Text(['Employees','Attendance','Leave','Payroll','Recruitment','Performance','Training','Compliance'][tab]+' management is available through the HR API and will use its dedicated workflow/configuration screens.'));}Widget _employees()=>ListView(children:[const Text('Employee Master',style:TextStyle(fontSize:22,fontWeight:FontWeight.bold)),const SizedBox(height:12),f('Employee Number',no),f('First Name',first),f('Last Name',last),f('Work Email',email),f('Joining Date (YYYY-MM-DD)',join),FilledButton.icon(onPressed:()async{try{await s.createEmployee({'employeeNo':no.text,'firstName':first.text,'lastName':last.text,'workEmail':email.text,'joiningDate':join.text,'employmentStatus':'ACTIVE'});if(mounted)ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Employee created')));}catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(e.toString())));}},icon:const Icon(Icons.person_add),label:const Text('Create Employee')),const SizedBox(height:16),if(s.error!=null)Text(s.error!),...s.employees.map((e)=>Card(child:ListTile(title:Text('${e['employee_no']} — ${e['first_name']} ${e['last_name']??''}'),subtitle:Text('${e['work_email']??''} • ${e['employment_status']}'),trailing:PopupMenuButton<String>(onSelected:(v)async{if(v=='in'||v=='out')await s.punch('${e['id']}',v=='in');},itemBuilder:(_)=>const[PopupMenuItem(value:'in',child:Text('Check In')),PopupMenuItem(value:'out',child:Text('Check Out'))]))))]);Widget _attendance()=>ListView(children:[const Text('Attendance & Time',style:TextStyle(fontSize:22,fontWeight:FontWeight.bold)),const SizedBox(height:12),...s.employees.map((e)=>Card(child:ListTile(title:Text('${e['employee_no']} — ${e['first_name']} ${e['last_name']??''}'),trailing:Wrap(spacing:8,children:[FilledButton(onPressed:()=>s.punch('${e['id']}',true),child:const Text('IN')),OutlinedButton(onPressed:()=>s.punch('${e['id']}',false),child:const Text('OUT'))]))))]);}
